import os, re, datetime
logs='/app/logs'; ref=datetime.date(2025,8,12)
sev={'ERROR':0,'WARNING':0,'INFO':0}; counts={}
def p_of(d):
    return {k:(v and d<=ref) for k,v in {
      'today': d==ref,
      'last_7_days': (ref-d)<datetime.timedelta(days=7),
      'last_30_days': (ref-d)<datetime.timedelta(days=30),
      'month_to_date': d.year==ref.year and d.month==ref.month,
      'total': True}.items()}
for f in os.listdir(logs):
    m=re.match(r'(\d{4}-\d{2}-\d{2})_',f)
    if not m: continue
    d=datetime.date.fromisoformat(m.group(1))
    periods=[k for k,v in p_of(d).items() if v]
    for line in open(os.path.join(logs,f)):
        for s in sev:
            if f'[{s}]' in line:
                sev[s]+=1
                for p in periods: counts.setdefault(p,{}).setdefault(s,0); counts[p][s]+=1
order=[(k,s) for k in ['today','last_7_days','last_30_days','month_to_date','total'] for s in ['ERROR','WARNING','INFO']]
with open('/app/summary.csv','w') as out:
    out.write('period,severity,count\n')
    for k,s in order: out.write(f'{k},{s},{counts.get(k,{}).get(s,0)}\n')
print(open('/app/summary.csv').read())
print("bracketed totals:",sev)
EOF
